int FuzzRB(const uint8_t *Data, size_t size) {
        mrb_value v;
        mrb_state *mrb = mrb_open();
        if (!mrb)
                return 0;

        char *code = (char *)malloc(size+1);
        if (!code)
                return 0;
        memcpy(code, Data, size);
        code[size] = '\0';

        if (const char *dump_path = getenv("PROTO_FUZZER_DUMP_PATH")) {
